function showToast(msg){toastEl.textContent=msg;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),1200)}
function cleanupGame(){gameCleanup.forEach(fn=>{try{fn()}catch{}});gameCleanup=[];clearInterval(balloonTimer);clearInterval(balloonMoveTimer);stopBalloonMusic();stopJiaJiaVoice()}
function gameTimeout(fn,ms){const id=setTimeout(fn,ms);gameCleanup.push(()=>clearTimeout(id));return id}

function ensureAudio(){if(!audioCtx) audioCtx = new (window.AudioContext||window.webkitAudioContext)()}
function tone(freq=540,dur=.12,type='sine',vol=.08){if(!state.sound)return; ensureAudio(); const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.value=vol;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+dur);o.stop(audioCtx.currentTime+dur)}
function sfxGood(){tone(650,.08,'sine',.08);setTimeout(()=>tone(880,.13,'sine',.07),70)}
function sfxBad(){tone(180,.16,'sawtooth',.05)}
function sfxBreak(){if(!state.sound)return;ensureAudio();const now=audioCtx.currentTime;const buffer=audioCtx.createBuffer(1,Math.floor(audioCtx.sampleRate*.18),audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/data.length,2.2);const src=audioCtx.createBufferSource(),g=audioCtx.createGain(),filter=audioCtx.createBiquadFilter();filter.type='highpass';filter.frequency.value=650;g.gain.setValueAtTime(.18,now);g.gain.exponentialRampToValueAtTime(.001,now+.18);src.buffer=buffer;src.connect(filter);filter.connect(g);g.connect(audioCtx.destination);src.start(now);tone(120,.11,'square',.06);setTimeout(()=>tone(85,.09,'square',.04),55)}
