function listenFindAnswer(b,c,t){if(c===t){b.classList.add('correct');sfxGood();speakWord(t);gameTimeout(gameListenFind,900)}else{b.classList.add('wrong');sfxBad();setTimeout(()=>b.classList.remove('wrong'),450)}}
function gameMemory(){
  let letters=state.selected.slice(0,Math.min(4,state.selected.length));if(letters.length<2)letters=ALPHABET.slice(0,4);
  const deck=shuffled(letters.flatMap(l=>[{k:l,type:'L',case:Math.random()<.5?'U':'L'},{k:l,type:'P'}]));
  gameHeader('Letter + Picture Memory',`<div class="instruction-strip">Match a letter flashcard with its picture. The extra memory-card frame has been removed.</div>`);
  document.getElementById('gameArea').innerHTML=`<div class="memory-grid">${deck.map((c,i)=>`<button class="memory-card" data-i="${i}" onclick="flipMem(this,${i})">?</button>`).join('')}</div>`;
  state.memDeck=deck;state.memOpen=[];state.memMatched=0
}
function flipMem(btn,i){
  if(btn.classList.contains('flipped')||btn.classList.contains('matched')||state.memOpen.length===2)return;
  const c=state.memDeck[i];btn.classList.add('flipped');
  btn.innerHTML=c.type==='L'?(c.case==='U'?upperLetterImg(c.k,'memory-letter-art'):lowerLetterImg(c.k,'memory-letter-art')):`<img class="memory-picture" src="${asset(c.k)}" alt="${DATA[c.k].word}">`;
  state.memOpen.push({btn,i,c});
  if(state.memOpen.length===2){const[a,b]=state.memOpen;if(a.c.k===b.c.k&&a.c.type!==b.c.type){a.btn.classList.add('matched');b.btn.classList.add('matched');state.memMatched+=2;state.memOpen=[];sfxGood();if(state.memMatched===state.memDeck.length){confetti();speak('Memory champion!')}}else setTimeout(()=>{[a,b].forEach(x=>{x.btn.classList.remove('flipped');x.btn.textContent='?'});state.memOpen=[];sfxBad()},800)}
}
function gameTrain(){
  const seq=state.selected.length>=3?state.selected.slice(0,Math.min(6,state.selected.length)):['A','B','C'];
  const missing=Math.floor(Math.random()*seq.length),answer=seq[missing],show=[...seq];show[missing]='?';
  const opts=shuffled([answer,...shuffled(ALPHABET.filter(x=>!seq.includes(x))).slice(0,3)]);
  gameHeader('ABC Train',`<button class="primary-btn" onclick="speakWord('${answer}')">🔊 Hear word</button>`);
  document.getElementById('gameArea').innerHTML=`<div class="train train-letter-art">${show.map(x=>`<div class="train-car">${x==='?'?'<span class="train-question">?</span>':mixedLetterImg(x,'letter-art train-letter-img')}</div>`).join('')}</div><div class="question-box"><h3>Which letter is missing?</h3><div class="answer-grid">${opts.map(o=>`<button class="answer-btn letter-image-btn" onclick="trainAnswer(this,'${o}','${answer}')">${mixedLetterImg(o)}</button>`).join('')}</div></div>`
}
function trainAnswer(b,c,t){if(c===t){b.classList.add('correct');sfxGood();speakWord(t);gameTimeout(gameTrain,900)}else{b.classList.add('wrong');sfxBad();setTimeout(()=>b.classList.remove('wrong'),450)}}
function gameWriting(){renderWrite()}
function gameFindLetter(){
  const t=rand(state.selected);const pool=Array.from({length:20},()=>Math.random()<.28?t:rand(ALPHABET));const total=pool.filter(x=>x===t).length;
  gameHeader('Find the Letter',`<div class="target-display find-target">Find all ${letterPairImg(t)}</div>`);
  document.getElementById('gameArea').innerHTML=`<div class="answer-grid letter-find-grid">${pool.map(x=>`<button class="answer-btn letter-image-btn" onclick="findHit(this,'${x}','${t}')">${mixedLetterImg(x)}</button>`).join('')}</div><div class="score-pill" style="margin-top:16px">Found: <span id="foundCount">0</span> / ${total}</div>`;state.findTotal=total;state.findFound=0
}
function findHit(b,c,t){if(c===t){if(b.disabled)return;b.disabled=true;b.classList.add('correct');state.findFound++;document.getElementById('foundCount').textContent=state.findFound;sfxGood();if(state.findFound===state.findTotal){confetti();speak('You found them all!')}}else{b.classList.add('wrong');sfxBad();setTimeout(()=>b.classList.remove('wrong'),400)}}

function gameSoundSort(){
  let letters=state.selected.slice(0,Math.min(3,state.selected.length));if(letters.length<2)letters=['B','D'];
  const pics=shuffled(letters.flatMap(l=>Array(2).fill(l)));
  gameHeader('Beginning Sound Sort',`<div class="instruction-strip"><b>How to play:</b> 1) Tap a picture to hear the word. 2) Listen to its first sound. 3) Tap the matching letter box.</div>`);
  document.getElementById('gameArea').innerHTML=`<div class="pair-stage sound-sort-stage">${letters.map(l=>`<div class="pair-col sound-bin" data-bin="${l}"><h3>${letterPairImg(l)}</h3><div class="sortBin" id="bin${l}"></div></div>`).join('')}</div><div class="card-row" style="margin-top:18px">${pics.map(l=>`<button class="phonics-card sort-picture" style="border:0" onclick="sortPic(this,'${l}')"><img src="${asset(l)}"><small>${DATA[l].word}</small></button>`).join('')}</div><p class="sort-help" id="sortHelp">Tap a picture first.</p>`;
  state.sortSelected=null;
  document.querySelectorAll('.pair-col').forEach(bin=>bin.onclick=()=>{if(!state.sortSelected){showToast('Tap a picture first');return}const good=bin.dataset.bin===state.sortSelected.dataset.l;if(good){bin.querySelector('.sortBin').appendChild(state.sortSelected);state.sortSelected.style.outline='';state.sortSelected.disabled=true;state.sortSelected=null;sfxGood();document.getElementById('sortHelp').textContent='Great! Choose another picture.'}else{sfxBad();document.getElementById('sortHelp').textContent='Try a different letter box.'}})
}
function sortPic(b,l){if(b.disabled)return;document.querySelectorAll('.sort-picture').forEach(x=>x.style.outline='');b.dataset.l=l;b.style.outline='5px solid #ffd84d';state.sortSelected=b;speakWord(l);const h=document.getElementById('sortHelp');if(h)h.textContent=`Now tap the letter that begins “${DATA[l].word}”.`}
function gameWheel(){
  gameHeader('Letter Wheel',`<div class="instruction-strip"><b>How to play:</b> Tap SPIN → watch the wheel → look at the big letter → say the letter name.</div>`);
  document.getElementById('gameArea').innerHTML=`<div class="wheel-stage"><div class="wheel" id="wheel"><span>?</span></div><div class="wheel-result-overlay" id="wheelResult"></div></div><div style="text-align:center"><button class="primary-btn" id="spinBtn" onclick="spinWheel()">SPIN</button></div>`
}
function spinWheel(){
  const w=document.getElementById('wheel'),result=document.getElementById('wheelResult'),btn=document.getElementById('spinBtn'),l=rand(state.selected),turns=5+Math.random()*3;if(!w||!result)return;btn.disabled=true;result.className='wheel-result-overlay';result.innerHTML='';w.querySelector('span').textContent='?';w.style.transform=`rotate(${turns*360+Math.random()*300}deg)`;gameTimeout(()=>{result.innerHTML=mixedLetterImg(l,'wheel-letter-img');result.classList.add('show');speakLetter(l);sfxGood();gameTimeout(()=>btn.disabled=false,700)},2500)
}
function gameWhack(){const t=rand(state.selected);gameHeader('Whack-a-Letter',`<div class="target-display">WHACK ${t}</div>`);const pool=Array.from({length:16},()=>Math.random()<.32?t:rand(state.selected.length>1?state.selected:ALPHABET));document.getElementById('gameArea').innerHTML=`<div class="answer-grid">${pool.map(x=>`<button class="answer-btn" style="border-radius:50%;background:#7a5637;color:white" onclick="whack(this,'${x}','${t}')">${x}</button>`).join('')}</div>`}
function whack(b,c,t){if(c===t){b.textContent='💥';b.disabled=true;sfxBreak()}else{sfxBad();b.classList.add('wrong');setTimeout(()=>b.classList.remove('wrong'),400)}}
function gameSpeak(){
  const l=rand(state.selected);gameHeader('Speaking Challenge',`<div class="instruction-strip">Listen and repeat slowly. There is a <b>3-second pause</b> between the letter, sound and word.</div>`);
  document.getElementById('gameArea').innerHTML=`<div class="question-box"><img src="${asset(l)}" style="width:min(330px,70vw);border-radius:24px"><h3>Say it aloud:</h3><div class="speaking-sequence" id="speakSeq"><span data-step="0">${l}${l.toLowerCase()}</span><b>•</b><span data-step="1">${DATA[l].sound}</span><b>•</b><span data-step="2">${DATA[l].word}</span></div><div class="selector-actions" style="justify-content:center"><button class="primary-btn" id="speakModelBtn" onclick="startSpeakingModel('${l}')">🔊 Slow Model</button><button class="secondary-btn" onclick="sfxGood();confetti();gameTimeout(gameSpeak,700)">✓ Student said it</button></div></div>`
}
function startSpeakingModel(l){
  const btn=document.getElementById('speakModelBtn'),seq=document.getElementById('speakSeq');if(btn)btn.disabled=true;
  const steps=seq?[...seq.querySelectorAll('[data-step]')]:[];const activate=i=>{steps.forEach((x,j)=>x.classList.toggle('active',i===j))};
  activate(0);speakLetter(l);
  const t1=setTimeout(()=>{activate(1);speakPhonic(l)},4000);
  const t2=setTimeout(()=>{activate(2);speakWord(l)},8000);
  const t3=setTimeout(()=>{activate(-1);if(btn)btn.disabled=false},11000);
  gameCleanup.push(()=>{clearTimeout(t1);clearTimeout(t2);clearTimeout(t3)})
}

function gameBoss(){state.bossHP=5;state.bossScore=0;gameHeader('Alphabet Boss',`<div class="score-pill">Boss HP: <span id="bossHp">5</span> ❤️</div>`);bossQuestion()}
function bossQuestion(){
  const area=document.getElementById('gameArea');
  if(state.bossHP<=0){const msg='Congratulations! You defeated the Alphabet Boss!';area.innerHTML=`<div class="result-panel"><div class="trophy">🏆</div><h2>Congratulations!</h2><p class="boss-congrats">You defeated the Alphabet Boss!</p><p>You mastered ${state.selected.join(' · ')}</p><button class="primary-btn" onclick="gameBoss()">Play Again</button></div>`;confetti();speak(msg);return}
  const t=rand(state.selected),opts=shuffled([t,...shuffled(state.selected.filter(x=>x!==t)).slice(0,3)]);
  area.innerHTML=`<div class="question-box"><div style="font-size:92px">👾</div><h3>Which letter starts ${DATA[t].word}?</h3><img src="${asset(t)}" style="width:220px;border-radius:20px"><div class="answer-grid">${opts.map(o=>`<button class="answer-btn letter-image-btn boss-answer" onclick="bossHit(this,'${o}','${t}')">${mixedLetterImg(o)}</button>`).join('')}</div><div class="boss-feedback" id="bossFeedback"></div></div>`
}
function bossHit(b,c,t){
  const fb=document.getElementById('bossFeedback');
  if(c===t){state.bossHP--;document.getElementById('bossHp').textContent=state.bossHP;sfxGood();document.querySelectorAll('.boss-answer').forEach(x=>x.disabled=true);b.classList.add('correct');const msg=rand(['Correct!','Great job!','Excellent!','You got it!','Amazing!']);if(fb){fb.textContent=msg;fb.className='boss-feedback good'}speak(msg);gameTimeout(bossQuestion,1300)}
  else{sfxBad();b.classList.add('wrong');if(fb){fb.textContent='Try again!';fb.className='boss-feedback try'}setTimeout(()=>b.classList.remove('wrong'),450)}
}
function gameBalloonRace(){state.race={teams:[0,0],active:0,target:rand(state.selected)};gameHeader('Balloon Letter Race');document.getElementById('gameArea').innerHTML=`<div class="game-toolbar"><div class="target-display">POP <span id="raceTarget">${state.race.target}</span></div><div class="team-panel"><div class="team-score active" id="team0">Team 1: <span>0</span></div><div class="team-score" id="team1">Team 2: <span>0</span></div></div><button class="soft-btn" onclick="raceChangeTarget()">New Target</button></div><div class="balloon-field" id="balloonField"></div>`;startRaceBalloons()}
function startRaceBalloons(){const field=document.getElementById('balloonField');const spawn=()=>{if(!field)return;const t=state.race.target,correct=Math.random()<.42,l=correct?t:rand(state.selected.length>1?state.selected.filter(x=>x!==t):ALPHABET.filter(x=>x!==t));const b=document.createElement('div');b.className='balloon';b.textContent=Math.random()<.5?l:l.toLowerCase();b.dataset.correct=correct;b.style.left=Math.random()*Math.max(20,field.clientWidth-90)+'px';b.style.bottom='-120px';b.style.background=rand(['#ff8798','#ffd95b','#68d4ff','#9bea7b','#c5a0ff','#ffb96a']);field.appendChild(b);let y=-120;const speed=(state.grade===1?1.15:1.75)+Math.random()*1.2;const mover=setInterval(()=>{y+=speed;b.style.bottom=y+'px';if(y>field.clientHeight+100){clearInterval(mover);b.remove()}},16);b.onclick=()=>{clearInterval(mover);const good=b.dataset.correct==='true';state.race.teams[state.race.active]+=good?1:-1;if(state.race.teams[state.race.active]<0)state.race.teams[state.race.active]=0;document.querySelector(`#team${state.race.active} span`).textContent=state.race.teams[state.race.active];good?sfxGood():sfxBad();b.classList.add('pop');setTimeout(()=>b.remove(),160);if(state.race.teams[state.race.active]>=10){cleanupGame();confetti();speak(`Team ${state.race.active+1} wins!`);setTimeout(()=>alert(`🏆 Team ${state.race.active+1} wins!`),250)}else if(good&&Math.random()<.35)raceChangeTarget();};gameCleanup.push(()=>clearInterval(mover))};balloonTimer=setInterval(spawn,state.grade===1?760:520);for(let i=0;i<7;i++)setTimeout(spawn,i*110);gameCleanup.push(()=>clearInterval(balloonTimer));const turn=setInterval(()=>{state.race.active=1-state.race.active;document.getElementById('team0')?.classList.toggle('active',state.race.active===0);document.getElementById('team1')?.classList.toggle('active',state.race.active===1)},12000);gameCleanup.push(()=>clearInterval(turn))}
function raceChangeTarget(){state.race.target=rand(state.selected);const el=document.getElementById('raceTarget');if(el)el.textContent=state.race.target;playJiaJiaSequence(['feedback_find',`letter_${state.race.target}`],90)}

function renderFinal(){state.final={q:0,score:0,total:10};finalQuestion()}
function finalQuestion(){if(state.final.q>=state.final.total){const pct=Math.round(state.final.score/state.final.total*100);shell('FINAL CHALLENGE — Complete','⭐',`<div class="result-panel"><div class="trophy">${pct>=80?'🏆':pct>=60?'⭐':'🌱'}</div><h2>${state.final.score} / ${state.final.total}</h2><p style="font-size:20px;color:var(--muted)">${pct>=80?'Excellent alphabet mastery!':pct>=60?'Good work — keep practicing!':'Great start — practice again and grow!'}</p><div class="selector-actions" style="justify-content:center"><button class="primary-btn" onclick="renderFinal()">Try Again</button><button class="secondary-btn" onclick="goHome()">Back to Menu</button></div></div>`);confetti();return}const t=rand(state.selected),mode=rand(['letter','word','case']);const distract=shuffled(state.selected.filter(x=>x!==t)).slice(0,state.grade===1?2:4),opts=shuffled([t,...distract]);shell(`FINAL CHALLENGE — ${state.final.q+1}/${state.final.total}`,'⭐',`<div class="progress"><div style="width:${state.final.q/state.final.total*100}%"></div></div><div class="question-box" style="margin-top:18px">${mode==='word'?`<img src="${asset(t)}" style="width:250px;border-radius:22px"><h3>Which letter starts this word?</h3>`:mode==='case'?`<div class="big-letter" style="font-size:120px">${t.toLowerCase()}</div><h3>Choose the uppercase letter</h3>`:`<h3>Listen and choose the letter</h3><button class="primary-btn" onclick="speakLetter('${t}')">🔊 Listen</button>`}<div class="answer-grid">${opts.map(o=>`<button class="answer-btn" onclick="finalAnswer(this,'${o}','${t}')">${o}</button>`).join('')}</div></div>`);if(mode==='letter')setTimeout(()=>speakLetter(t),400)}
function finalAnswer(b,c,t){state.final.q++;if(c===t){state.final.score++;b.classList.add('correct');sfxGood()}else{b.classList.add('wrong');sfxBad()}setTimeout(finalQuestion,650)}

window.addEventListener('load',()=>{goHome();primeJiaJiaVoice()});
document.addEventListener('pointerdown',()=>{ensureAudio();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});primeJiaJiaVoice();primeBalloonPopAudio()},{passive:true});
